};

import React, { useMemo } from 'react';
import { VintageScore } from '../types';

interface VintageChartProps {
  data: VintageScore[];
  currentVintage: string;
}

export const VintageChart: React.FC<VintageChartProps> = ({ data, currentVintage }) => {
  const sortedData = useMemo(() => {
    return [...data].sort((a, b) => parseInt(a.year) - parseInt(b.year));
  }, [data]);

  if (sortedData.length < 2) return null;

  const scores = sortedData.map(d => d.score);
  const avgScore = Math.round(scores.reduce((a, b) => a + b, 0) / scores.length);

  const minScore = Math.min(...scores);
  const maxScore = Math.max(...scores);

  const minY = Math.max(0, minScore - 3);
  const maxY = Math.min(100, maxScore + 2);
  const rangeY = maxY - minY;

  const width = 600; 
  const height = 240;
  const paddingX = 40;
  const paddingY = 30;
  const graphWidth = width - (paddingX * 2);
  const graphHeight = height - (paddingY * 2);

  const getX = (index: number) => {
    const count = sortedData.length;
    if (count === 1) return width / 2;
    const step = graphWidth / (count - 1);
    return paddingX + (index * step);
  };

  const getY = (score: number) => {
    const normalized = (score - minY) / (rangeY || 1);
    return paddingY + graphHeight - (normalized * graphHeight);
  };

  const yAvg = getY(avgScore);

  const points = sortedData.map((d, i) => ({
    x: getX(i),
    y: getY(d.score),
    ...d
  }));

  const linePath = points.map((p, i) => `${i === 0 ? 'M' : 'L'} ${p.x} ${p.y}`).join(' ');

  const areaPath = `
    ${linePath}
    L ${points[points.length - 1].x} ${height - paddingY}
    L ${points[0].x} ${height - paddingY}
    Z
  `;

  return (
    <div className="w-full select-none">
      <div className="relative w-full aspect-[2.5/1] max-h-60">
        <svg 
            viewBox={`0 0 ${width} ${height}`} 
            className="w-full h-full overflow-visible font-sans"
            preserveAspectRatio="none"
        >
          <defs>
            <linearGradient id="lineGradient" x1="0" y1="0" x2="1" y2="0">
              <stop offset="0%" stopColor="#f59e0b" />
              <stop offset="100%" stopColor="#d97706" />
            </linearGradient>
            <linearGradient id="areaGradient" x1="0" y1="0" x2="0" y2="1">
              <stop offset="0%" stopColor="#f59e0b" stopOpacity="0.25"/>
              <stop offset="100%" stopColor="#f59e0b" stopOpacity="0"/>
            </linearGradient>
            <filter id="shadow" x="-20%" y="-20%" width="140%" height="140%">
               <feDropShadow dx="0" dy="4" stdDeviation="4" floodOpacity="0.3"/>
            </filter>
            <filter id="glow" x="-50%" y="-50%" width="200%" height="200%">
               <feGaussianBlur stdDeviation="2.5" result="coloredBlur"/>
               <feMerge>
                   <feMergeNode in="coloredBlur"/>
                   <feMergeNode in="SourceGraphic"/>
               </feMerge>
            </filter>
          </defs>

          {[minY, (minY + maxY) / 2, maxY].map((val, i) => {
              const y = getY(val);
              return (
                  <g key={i}>
                      <line x1={paddingX} y1={y} x2={width - paddingX} y2={y} stroke="#ffffff" strokeWidth="1" strokeOpacity="0.1" />
                      <text x={paddingX - 12} y={y + 4} textAnchor="end" className="text-xs fill-slate-300 font-medium tabular-nums">
                        {Math.round(val)}
                      </text>
                  </g>
              )
          })}

           <line x1={paddingX} y1={yAvg} x2={width - paddingX} y2={yAvg} stroke="#94a3b8" strokeWidth="1" strokeDasharray="4,4" strokeOpacity="0.5" />
           <text x={width - paddingX + 6} y={yAvg + 3} className="text-[10px] fill-slate-300 font-bold uppercase tracking-widest">Avg {avgScore}</text>

          <path d={areaPath} fill="url(#areaGradient)" />
          <path d={linePath} fill="none" stroke="url(#lineGradient)" strokeWidth="2.5" strokeLinecap="round" strokeLinejoin="round" style={{ filter: 'url(#shadow)' }} />

          {points.map((p, i) => {
             const isCurrent = p.year === currentVintage;
             return (
               <g key={p.year}>
                 <circle 
                    cx={p.x} 
                    cy={p.y} 
                    r={isCurrent ? 5 : 3.5} 
                    fill={isCurrent ? "#f59e0b" : "#1e293b"} 
                    stroke={isCurrent ? "#ffffff" : "#94a3b8"} 
                    strokeWidth={isCurrent ? 2 : 1.5}
                    style={{ filter: isCurrent ? 'url(#glow)' : 'none' }}
                 />
                 <text 
                    x={p.x} 
                    y={p.y - 12} 
                    textAnchor="middle" 
                    className={`text-sm tracking-tight ${isCurrent ? 'fill-gold-400 font-bold' : 'fill-slate-300 font-medium'}`}
                 >
                    {p.score}
                 </text>
                 <text 
                    x={p.x} 
                    y={height - 8} 
                    textAnchor="middle" 
                    className={`text-xs tracking-tight ${isCurrent ? 'fill-white font-bold' : 'fill-slate-400 font-medium'}`}
                 >
                    {p.year}
                 </text>
               </g>
             );
          })}
        </svg>
      </div>
    </div>
  );
};

import React from 'react';
import { GrapeComposition } from '../types';

interface CompositionChartProps {
  data: GrapeComposition[];
}

export const CompositionChart: React.FC<CompositionChartProps> = ({ data }) => {
  if (!data || data.length === 0) return null;

  const total = data.reduce((acc, curr) => acc + curr.percentage, 0);
  let cumulativePercent = 0;

  const getCoordinatesForPercent = (percent: number) => {
    const x = Math.cos(2 * Math.PI * percent);
    const y = Math.sin(2 * Math.PI * percent);
    return [x, y];
  };

  const colors = [
    '#882333',
    '#c3354b',
    '#e58796',
    '#f6d5da',
    '#d6d3d1',
  ];

  const slices = data.map((slice, index) => {
    const startPercent = cumulativePercent;
    const endPercent = cumulativePercent + (slice.percentage / total);
    cumulativePercent = endPercent;

    const [startX, startY] = getCoordinatesForPercent(startPercent - 0.25);
    const [endX, endY] = getCoordinatesForPercent(endPercent - 0.25);

    if (slice.percentage >= 100) {
      return {
        path: `M 1 0 A 1 1 0 1 1 -1 0 A 1 1 0 1 1 1 0`,
        color: colors[index % colors.length],
        label: slice.grape,
        percent: slice.percentage
      };
    }

    const largeArcFlag = slice.percentage / total > 0.5 ? 1 : 0;

    const pathData = [
      `M ${startX} ${startY}`,
      `A 1 1 0 ${largeArcFlag} 1 ${endX} ${endY}`,
      `L 0 0`,
    ].join(' ');

    return {
      path: pathData,
      color: colors[index % colors.length],
      label: slice.grape,
      percent: slice.percentage
    };
  });

  return (
    <div className="flex flex-col sm:flex-row items-center gap-6">
      <div className="relative w-32 h-32 shrink-0">
        <svg viewBox="-1 -1 2 2" className="w-full h-full -rotate-90">
           {slices.map((slice, i) => (
             <path 
               key={i} 
               d={slice.path} 
               fill={slice.color} 
               stroke="white" 
               strokeWidth="0.05"
             />
           ))}
           <circle cx="0" cy="0" r="0.6" fill="white" />
        </svg>
        <div className="absolute inset-0 flex items-center justify-center pointer-events-none">
            <span className="text-[10px] font-bold text-stone-400 uppercase tracking-widest">Blend</span>
        </div>
      </div>

      <div className="flex-1 w-full grid grid-cols-2 sm:grid-cols-1 gap-2">
         {slices.map((slice, i) => (
            <div key={i} className="flex items-center gap-2">
               <div className="w-3 h-3 rounded-full shrink-0" style={{ backgroundColor: slice.color }}></div>
               <div className="flex flex-col leading-none">
                   <span className="text-sm font-bold text-wine-900">{slice.percent}%</span>
                   <span className="text-xs text-stone-500 font-medium">{slice.label}</span>
               </div>
            </div>
         ))}
      </div>
    </div>
  );
};

