import React, { useState, useEffect } from 'react';
import { WineData, LegendaryVintage } from '../types';
import { MapPin, Droplet, TrendingUp, Utensils, Thermometer, Wine as WineIcon, Mountain, ExternalLink, Lightbulb, Clock, BookOpen, ChevronDown, ChevronUp, Activity, FileDown, Award, Star, PenLine, Sparkles, GraduationCap, Sun, Plus, Package } from 'lucide-react';
