interface WineDisplayProps {
  data: WineData;
  imagePreview: string | null;
  isFavorite: boolean;
  onToggleFavorite: () => void;
  onUpdateWine: (updatedData: WineData) => void;
  onAddToCellar: (wine: WineData, quantity: number, price?: number) => void;
}

const countryCodeMap: Record<string, string> = {
  'italy': 'it', 'france': 'fr', 'spain': 'es', 'united states': 'us', 'usa': 'us',
  'argentina': 'ar', 'chile': 'cl', 'australia': 'au', 'germany': 'de', 'portugal': 'pt',
  'south africa': 'za', 'new zealand': 'nz', 'austria': 'at', 'hungary': 'hu', 'greece': 'gr'
};

const StyleMeter = ({ label, value }: { label: string; value: string }) => {
  const getPercentage = (val: string) => {
    const v = val.toLowerCase();
    if (v.includes('high') || v.includes('full')) return 90;
    if (v.includes('medium')) return 50;
    if (v.includes('low') || v.includes('light')) return 25;
    return 60;
  };

  const pct = getPercentage(value);

  return (
    <div className="mb-4">
      <div className="flex justify-between text-xs font-bold mb-1">
        <span className="text-stone-400 uppercase tracking-wide">{label}</span>
        <span className="text-wine-900">{value}</span>
      </div>
      <div className="h-1.5 w-full bg-stone-100 rounded-full overflow-hidden">
        <div className="h-full bg-wine-500 rounded-full" style={{ width: `${pct}%` }}></div>
      </div>
    </div>
  );
};

const CollapsibleSection = ({ title, icon: Icon, children, defaultOpen = false }: { title: string; icon: React.ElementType; children?: React.ReactNode; defaultOpen?: boolean }) => {
  const [isOpen, setIsOpen] = useState(defaultOpen);
  return (
    <div className="bg-white rounded-2xl overflow-hidden mb-4 border border-stone-100">
      <button onClick={() => setIsOpen(!isOpen)} className="w-full flex items-center justify-between p-4 hover:bg-stone-50 transition-colors">
        <div className="flex items-center gap-3">
          <div className="p-2 bg-wine-50 rounded-lg text-wine-600"><Icon className="w-4 h-4" /></div>
          <span className="font-bold text-wine-950">{title}</span>
        </div>
        {isOpen ? <ChevronUp className="w-4 h-4 text-stone-300" /> : <ChevronDown className="w-4 h-4 text-stone-300" />}
      </button>
      {isOpen && <div className="p-4 pt-0 border-t border-stone-50">{children}</div>}
    </div>
  );
};

export const WineDisplay: React.FC<WineDisplayProps> = ({ data, imagePreview, isFavorite, onToggleFavorite, onUpdateWine, onAddToCellar }) => {
  const [currentImageIndex, setCurrentImageIndex] = useState(0);
  const [usingFallback, setUsingFallback] = useState(false);
  const [showCellarModal, setShowCellarModal] = useState(false);
  const [cellarQty, setCellarQty] = useState(1);
  const [cellarPrice, setCellarPrice] = useState('');
  const [noteText, setNoteText] = useState(data.userNotes || '');

  useEffect(() => {
    setCurrentImageIndex(0);
    setUsingFallback(false);
    setNoteText(data.userNotes || '');
  }, [data]);

  const fallbackImage = 'https://images.unsplash.com/photo-1559563362-c667ba5f5480?auto=format&fit=crop&q=80&w=600';

  const getFlagUrl = () => {
      if (!data.country) return null;
      const key = data.country.toLowerCase().trim();
      if (countryCodeMap[key]) return `https://flagcdn.com/w640/${countryCodeMap[key]}.png`;
      return null;
  };

  const getDisplayImage = () => {
    if (imagePreview) return imagePreview;
    if (usingFallback) return getFlagUrl() || fallbackImage;
    const candidates = data.imageCandidates || (data.onlineImage ? [data.onlineImage] : []);
    if (candidates.length > 0 && currentImageIndex < candidates.length) return candidates[currentImageIndex];
    return getFlagUrl() || fallbackImage;
  };

  const handleImageError = () => {
    const candidates = data.imageCandidates || (data.onlineImage ? [data.onlineImage] : []);
    if (currentImageIndex < candidates.length - 1) setCurrentImageIndex(prev => prev + 1);
    else setUsingFallback(true);
  };

  const displayImage = getDisplayImage();
  const mapUrl = `https://www.google.com/maps/search/?api=1&query=${encodeURIComponent(data.region + ', ' + data.country)}`;

  const handleRating = (rating: number) => onUpdateWine({ ...data, userRating: rating });
  const handleNoteBlur = () => { if (noteText !== data.userNotes) onUpdateWine({ ...data, userNotes: noteText }); };
  const handleAddToCellarSubmit = () => { onAddToCellar(data, cellarQty, cellarPrice ? parseFloat(cellarPrice) : undefined); setShowCellarModal(false); };

  return (
    <div className="pb-32 space-y-6 px-4">
      <div className="bg-white rounded-[2.5rem] p-6 shadow-xl shadow-wine-900/5 overflow-hidden relative border border-stone-100">
        <div className="flex gap-4 mb-6">
          <div className="w-24 shrink-0 aspect-[3/4] rounded-xl overflow-hidden bg-stone-100 shadow-md">
            <img src={displayImage} onError={handleImageError} className="w-full h-full object-cover" alt={data.name} />
          </div>
          <div className="flex-1 flex flex-col justify-center min-w-0">
              <a href={mapUrl} target="_blank" rel="noopener noreferrer" className="flex items-center gap-1 text-wine-500 text-[10px] font-bold uppercase tracking-wider mb-1">
                  <MapPin className="w-3 h-3" /> {data.region}, {data.country}
              </a>
              <h2 className="text-2xl font-serif font-black text-wine-900 leading-tight mb-2 line-clamp-3">{data.name}</h2>
              <div className="flex flex-wrap gap-1">
                 {data.varietals.slice(0, 2).map(v => (
                   <span key={v} className="text-[10px] font-bold text-stone-500 uppercase px-2 py-0.5 bg-stone-100 rounded-md">{v}</span>
                 ))}
              </div>
          </div>
        </div>
        <div className="grid grid-cols-2 gap-4 bg-wine-50/50 p-4 rounded-2xl border border-wine-100/50">
            <div className="text-center border-r border-wine-100/50">
                <span className="text-[10px] font-bold text-stone-400 uppercase block mb-1">Price</span>
                <span className="text-lg font-bold text-wine-900">{data.marketPrice}</span>
            </div>
            <div className="text-center">
                <span className="text-[10px] font-bold text-stone-400 uppercase block mb-1">Sommelier</span>
                <span className="text-lg font-bold text-wine-900">{data.criticScores?.[0]?.score || 'N/A'}/100</span>
            </div>
        </div>
      </div>

      <div className="bg-white rounded-3xl p-6 border border-stone-100 shadow-sm">
          <h3 className="text-sm font-bold text-stone-400 uppercase tracking-widest mb-6 flex items-center gap-2"><Activity className="w-4 h-4 text-wine-500" /> Sensory Analysis</h3>
          <div className="grid grid-cols-1 gap-2 mb-8">
              <StyleMeter label="Body" value={data.styleProfile?.body || 'Medium'} />
              <StyleMeter label="Acidity" value={data.styleProfile?.acidity || 'Medium'} />
              <StyleMeter label="Tannins" value={data.styleProfile?.tannins || 'Medium'} />
          </div>
          <div className="space-y-4">
              <div className="flex items-center gap-2 text-wine-900 mb-2"><Droplet className="w-4 h-4" /><span className="text-xs font-bold uppercase">Aromatic Profile</span></div>
              <div className="flex flex-wrap gap-1.5">
                  {[...data.nose.split(','), ...data.taste.split(',')].slice(0, 6).map((note, i) => (
                      <span key={i} className="px-3 py-1.5 bg-stone-50 text-stone-600 text-xs font-medium rounded-full border border-stone-100">{note.trim()}</span>
                  ))}
              </div>
          </div>
          <div className="grid grid-cols-3 gap-2 mt-8 pt-6 border-t border-stone-50 text-center">
              <div><Thermometer className="w-4 h-4 text-stone-300 mx-auto mb-1" /><span className="text-[10px] font-bold text-stone-500 uppercase">{data.pairing?.temperature || '16°C'}</span></div>
              <div><WineIcon className="w-4 h-4 text-stone-300 mx-auto mb-1" /><span className="text-[10px] font-bold text-stone-500 uppercase">{data.pairing?.glassware.split(' ')[0] || 'Glass'}</span></div>
