              <div className="text-center"><span className="text-[10px] text-wine-300 uppercase block mb-1">Until</span><span className="text-2xl font-serif font-bold">{data.aging?.drinkUntil}</span></div>
          </div>
          {data.vintageComparison && (
              <div className="bg-white/5 rounded-2xl p-4 border border-white/10 mb-6">
                  <p className="text-[10px] font-bold text-wine-300 uppercase tracking-widest mb-4">Vintage Trajectory</p>
                  <VintageChart data={data.vintageComparison} currentVintage={data.vintage} />
              </div>
          )}
          <div className="p-4 bg-white/5 rounded-xl border border-white/5"><p className="text-wine-100 text-sm italic leading-relaxed font-medium">"{data.aging?.estimatedValue5Years}"</p></div>
      </div>

      <div className="space-y-4">
          {data.education && (
              <CollapsibleSection title="Education & Insight" icon={GraduationCap}>
                  <div className="space-y-6">
                      <div><span className="text-[10px] font-bold text-stone-400 uppercase block mb-1">Pronunciation</span><div className="flex items-baseline gap-2"><span className="text-xl font-serif font-bold text-wine-950">{data.education.pronunciation.native}</span><span className="text-xs text-stone-400 font-medium italic">/{data.education.pronunciation.phonetic}/</span></div></div>
                      <div className="bg-stone-50 p-4 rounded-xl border border-stone-100"><div className="grid grid-cols-2 gap-4 mb-4"><div><Sun className="w-4 h-4 text-wine-500 mb-1" /><span className="text-[10px] font-bold text-stone-400 uppercase block">Climate</span><span className="text-xs font-bold text-stone-700">{data.education.climate}</span></div><div><Mountain className="w-4 h-4 text-wine-500 mb-1" /><span className="text-[10px] font-bold text-stone-400 uppercase block">Terroir</span><span className="text-xs font-bold text-stone-700">{data.education.geography}</span></div></div><p className="text-xs font-medium italic text-stone-500 border-t border-stone-200 pt-3 leading-relaxed">"{data.education.vibe}"</p></div>
                  </div>
              </CollapsibleSection>
          )}
          {data.terroir && (
              <CollapsibleSection title="Terroir & Winemaking" icon={Mountain}>
                  <div className="space-y-6">
                      <CompositionChart data={data.grapeComposition || []} />
                      <div className="grid gap-4">
                          <div><span className="text-[10px] font-bold text-stone-400 uppercase block mb-1">Soil Signature</span><p className="text-sm font-bold text-stone-800">{data.terroir.soil.join(', ')}</p></div>
                          <div><span className="text-[10px] font-bold text-stone-400 uppercase block mb-1">Oak Strategy</span><p className="text-sm font-bold text-stone-800">{data.terroir.oak}</p></div>
                      </div>
                  </div>
              </CollapsibleSection>
