import React, { useState, useEffect } from 'react';
import { Header } from './components/Header';
import { ScanButton } from './components/ScanButton';
import { WineDisplay } from './components/WineDisplay';
import { CellarDashboard } from './components/CellarDashboard';
import { analyzeWineLabel, searchWineByName } from './services/geminiService';
import { AnalysisState, WineData, CellarItem } from './types';
import { Loader2, AlertCircle, Search, ArrowRight, Sparkles } from 'lucide-react';

const WineListItemThumbnail = ({ src }: { src?: string }) => {
  const [error, setError] = useState(false);
  if (!src || error) {
    return <div className="w-full h-full flex items-center justify-center bg-stone-100 text-stone-300"><span className="text-[10px] font-black">AI</span></div>;
  }
  return <img src={src} alt="" className="w-full h-full object-cover" onError={() => setError(true)} />;
};

const App: React.FC = () => {
  const [imagePreview, setImagePreview] = useState<string | null>(null);
  const [analysis, setAnalysis] = useState<AnalysisState>({ status: 'idle' });
  const [searchQuery, setSearchQuery] = useState('');
  const [history, setHistory] = useState<WineData[]>([]);
  const [cellar, setCellar] = useState<CellarItem[]>([]);
  const [activeTab, setActiveTab] = useState<'recent' | 'cellar'>('recent');

  useEffect(() => {
    try {
      const savedHistory = localStorage.getItem('wineHistory');
      if (savedHistory) setHistory(JSON.parse(savedHistory));
      const savedCellar = localStorage.getItem('wineCellar');
      if (savedCellar) setCellar(JSON.parse(savedCellar));
    } catch (e) { console.error(e); }
  }, []);

  const saveToHistory = (data: WineData) => {
    setHistory(prev => {
      const filtered = prev.filter(item => !(item.name === data.name && item.vintage === data.vintage));
      const newHistory = [data, ...filtered].slice(0, 10);
      localStorage.setItem('wineHistory', JSON.stringify(newHistory));
      return newHistory;
    });
  };

  const handleWineUpdate = (updatedData: WineData) => {
    if (analysis.status === 'success' && analysis.data?.id === updatedData.id) {
        setAnalysis(prev => ({ ...prev, data: updatedData }));
    }
    setHistory(prev => {
        const newHist = prev.map(item => (item.id === updatedData.id ? updatedData : item));
        localStorage.setItem('wineHistory', JSON.stringify(newHist));
        return newHist;
    });
    setCellar(prev => {
        const newCellar = prev.map(item => item.wine.id === updatedData.id ? { ...item, wine: updatedData } : item);
        localStorage.setItem('wineCellar', JSON.stringify(newCellar));
        return newCellar;
    });
  };

  const handleAddToCellar = (wine: WineData, quantity: number, price?: number) => {
      setCellar(prev => {
          const existingIndex = prev.findIndex(i => i.wine.name === wine.name && i.wine.vintage === wine.vintage);
          let newCellar;
          if (existingIndex >= 0) {
              newCellar = [...prev];
              newCellar[existingIndex].quantity += quantity;
              if (price) newCellar[existingIndex].purchasePrice = price;
          } else {
              const newItem: CellarItem = {
                  id: `${Date.now()}-${Math.random()}`,
                  wine, quantity, purchasePrice: price, addedAt: Date.now()
              };
              newCellar = [newItem, ...prev];
          }
          localStorage.setItem('wineCellar', JSON.stringify(newCellar));
          return newCellar;
      });
  };

  const updateCellarQuantity = (id: string, delta: number) => {
      setCellar(prev => {
          const newCellar = prev.map(item => item.id === id ? { ...item, quantity: Math.max(0, item.quantity + delta) } : item).filter(item => item.quantity > 0);
          localStorage.setItem('wineCellar', JSON.stringify(newCellar));
          return newCellar;
      });
  };

  const removeCellarItem = (id: string) => {
      setCellar(prev => {
          const newCellar = prev.filter(item => item.id !== id);
          localStorage.setItem('wineCellar', JSON.stringify(newCellar));
          return newCellar;
      });
  };

  const handleImageSelect = async (file: File) => {
    const reader = new FileReader();
    reader.onloadend = () => setImagePreview(reader.result as string);
    reader.readAsDataURL(file);
    setAnalysis({ status: 'analyzing' });
    try {
      const base64Data = await new Promise<string>((resolve, reject) => {
        const r = new FileReader();
        r.readAsDataURL(file);
        r.onload = () => resolve((r.result as string).split(',')[1]);
        r.onerror = e => reject(e);
      });
      const data = await analyzeWineLabel(base64Data, file.type);
      setAnalysis({ status: 'success', data });
      saveToHistory(data);
    } catch (e) { setAnalysis({ status: 'error', error: "Could not identify label" }); }
  };

  const handleTextSearch = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!searchQuery.trim()) return;
    setImagePreview(null);
    setAnalysis({ status: 'analyzing' });
    try {
      const data = await searchWineByName(searchQuery);
      setAnalysis({ status: 'success', data });
      saveToHistory(data);
    } catch (e) { setAnalysis({ status: 'error', error: "Wine not found" }); }
  };

  return (
    <div className="min-h-screen bg-wine-50 flex flex-col">
      <Header />

      <main className="max-w-md mx-auto w-full flex-grow px-4 pb-40">

        {analysis.status === 'idle' && (
          <div className="flex justify-center gap-6 mb-8">
              <button 
                onClick={() => setActiveTab('recent')} 
                className={`text-xs font-bold uppercase tracking-widest transition-all pb-1 border-b-2 ${activeTab === 'recent' ? 'border-wine-800 text-wine-900' : 'border-transparent text-stone-300'}`}
              >
                Search
              </button>
              <button 
                onClick={() => setActiveTab('cellar')} 
                className={`text-xs font-bold uppercase tracking-widest transition-all pb-1 border-b-2 ${activeTab === 'cellar' ? 'border-wine-800 text-wine-900' : 'border-transparent text-stone-300'}`}
              >
                Cellar
              </button>
          </div>
        )}

        {analysis.status === 'idle' && activeTab === 'cellar' && (
           <CellarDashboard items={cellar} onUpdateQuantity={updateCellarQuantity} onRemoveItem={removeCellarItem} onViewWine={(w) => { setAnalysis({ status: 'success', data: w }); setActiveTab('recent'); }} />
        )}

        {analysis.status === 'idle' && activeTab === 'recent' && (
          <div className="space-y-8 animate-fade-in">
            <div className="bg-white rounded-3xl p-6 shadow-sm border border-stone-100">
              <h2 className="text-xl font-serif font-black text-wine-900 mb-4 italic">Manual Search</h2>
              <form onSubmit={handleTextSearch} className="relative mb-4">
                <input 
                  type="text"
                  placeholder="Vintage, Estate, or Varietal..."
                  value={searchQuery}
                  onChange={(e) => setSearchQuery(e.target.value)}
                  className="w-full bg-stone-50 border-none py-4 px-4 pr-12 rounded-xl text-stone-800 placeholder:text-stone-300 focus:ring-2 focus:ring-wine-500 transition-all font-medium"
                />
                <button type="submit" disabled={!searchQuery.trim()} className="absolute right-3 top-1/2 -translate-y-1/2 text-wine-600 disabled:text-stone-300 transition-colors">
                  <ArrowRight className="w-6 h-6" />
                </button>
              </form>
              <div className="flex items-start gap-3 p-4 bg-wine-50/50 rounded-xl">
                <Sparkles className="w-4 h-4 text-wine-500 mt-1 shrink-0" />
                <p className="text-[11px] font-medium text-wine-800 leading-relaxed">Specify the vintage year for the most accurate historical reports and market pricing.</p>
              </div>
            </div>

            <div className="space-y-4">
                <h3 className="text-xs font-bold text-stone-400 uppercase tracking-widest ml-1">Recent Searches</h3>
                <div className="space-y-3">
                    {history.length > 0 ? history.map((item, idx) => (
                        <div key={idx} onClick={() => { setAnalysis({ status: 'success', data: item }); setImagePreview(item.onlineImage || null); }} className="bg-white rounded-2xl p-3 flex items-center gap-4 hover:shadow-md cursor-pointer transition-all border border-stone-50 active:scale-[0.98]">
                            <div className="w-12 h-12 bg-stone-100 rounded-xl overflow-hidden shrink-0">
                                <WineListItemThumbnail src={item.onlineImage} />
                            </div>
                            <div className="flex-1 min-w-0">
                                <p className="font-bold text-wine-900 text-sm truncate">{item.name}</p>
                                <p className="text-[10px] font-bold text-stone-400 uppercase mt-0.5">{item.vintage} • {item.region}</p>
                            </div>
                            <span className="text-sm font-bold text-gold-400 pr-1">{item.criticScores?.[0]?.score || '-'}</span>
                        </div>
                    )) : <p className="text-center text-stone-300 text-xs italic py-8">Your search history will appear here.</p>}
                </div>
            </div>
          </div>
        )}

        {analysis.status === 'analyzing' && (
          <div className="flex flex-col items-center justify-center py-20 px-6 text-center">
            <div className="relative mb-8">
              <div className="absolute inset-0 bg-wine-100 rounded-full animate-ping opacity-50"></div>
              <div className="relative bg-white p-6 rounded-full shadow-lg border border-stone-50">
                <Loader2 className="w-10 h-10 text-wine-800 animate-spin" />
              </div>
            </div>
            <h3 className="text-xl font-serif font-black text-wine-900 mb-2">Analyzing Label</h3>
            <p className="text-stone-400 text-xs font-bold uppercase tracking-widest">Identifying varietal & estate...</p>
          </div>
        )}

        {analysis.status === 'success' && analysis.data && (
          <div className="animate-slide-up">
            <button onClick={() => { setAnalysis({ status: 'idle' }); setSearchQuery(''); setImagePreview(null); }} className="mb-4 ml-4 text-[10px] font-bold text-stone-400 uppercase tracking-widest hover:text-wine-800 transition-colors flex items-center gap-2">
              <ArrowRight className="w-3 h-3 rotate-180" /> Back to Dashboard
            </button>
            <WineDisplay data={analysis.data} imagePreview={imagePreview} isFavorite={false} onToggleFavorite={() => {}} onUpdateWine={handleWineUpdate} onAddToCellar={handleAddToCellar} />
          </div>
        )}

        {analysis.status === 'error' && (
          <div className="text-center py-20 px-10">
            <AlertCircle className="w-12 h-12 text-wine-600 mx-auto mb-4" />
            <h3 className="text-xl font-serif font-black text-wine-900 mb-2">Scan Failed</h3>
            <p className="text-stone-500 text-sm mb-8">Unable to identify this label. Please try again with better lighting or search manually.</p>
            <button onClick={() => setAnalysis({ status: 'idle' })} className="px-8 py-4 bg-wine-900 text-white rounded-full text-xs font-bold uppercase tracking-wider shadow-xl">Retry Scan</button>
          </div>
        )}

      </main>

      {(analysis.status === 'idle' || analysis.status === 'analyzing') && (
        <ScanButton 
          onImageSelect={handleImageSelect} 
          disabled={analysis.status === 'analyzing'} 
        />
      )}

      <footer className="w-full py-10 text-center border-t border-stone-100">
        <p className="text-[10px] uppercase tracking-[0.3em] text-stone-300 font-bold">MagmaTek • Sommelier AI v2.7</p>
      </footer>
    </div>
  );
};

