};

const StyleMeter = ({ label, value }: { label: string; value: string }) => {
  const getPercentage = (val: string) => {
    const v = val.toLowerCase();
    if (v.includes('high') || v.includes('full')) return 90;
    if (v.includes('medium')) return 50;
    if (v.includes('low') || v.includes('light')) return 25;
    return 60;
  };

  const pct = getPercentage(value);

  return (
    <div className="mb-6">
      <div className="flex justify-between items-end mb-2">
        <span className="text-[10px] uppercase tracking-widest font-black text-stone-400">{label}</span>
        <span className="text-xs font-bold text-velvet-950">{value}</span>
      </div>
      <div className="h-1 w-full bg-stone-200/50 rounded-full overflow-hidden">
        <div 
          className="h-full bg-dustyGold-500 transition-all duration-1000 ease-out" 
          style={{ width: `${pct}%` }}
        ></div>
      </div>
    </div>
  );
};

