export const WineDisplay: React.FC<WineDisplayProps> = ({ data, imagePreview, onAddToCellar }) => {
  const [currentImageIndex, setCurrentImageIndex] = useState(0);
  const [usingFallback, setUsingFallback] = useState(false);
  const [showCellarModal, setShowCellarModal] = useState(false);
  const [cellarQty, setCellarQty] = useState(1);
  const [cellarPrice, setCellarPrice] = useState('');

  useEffect(() => {
    setCurrentImageIndex(0);
    setUsingFallback(false);
  }, [data]);

  const fallbackImage = 'https://images.unsplash.com/photo-1559563362-c667ba5f5480?auto=format&fit=crop&q=80&w=600';

  const getFlagUrl = () => {
      if (!data.country) return null;
      const key = data.country.toLowerCase().trim();
      if (countryCodeMap[key]) return `https://flagcdn.com/w640/${countryCodeMap[key]}.png`;
      return null;
  };

  const getDisplayImage = () => {
    if (imagePreview) return imagePreview;
    if (usingFallback) return getFlagUrl() || fallbackImage;
    const candidates = data.imageCandidates || (data.onlineImage ? [data.onlineImage] : []);
    if (candidates.length > 0 && currentImageIndex < candidates.length) return candidates[currentImageIndex];
    return getFlagUrl() || fallbackImage;
  };

  const handleImageError = () => {
    const candidates = data.imageCandidates || (data.onlineImage ? [data.onlineImage] : []);
    if (currentImageIndex < candidates.length - 1) setCurrentImageIndex(prev => prev + 1);
    else setUsingFallback(true);
  };

  const displayImage = getDisplayImage();
  const mapUrl = `https://www.google.com/maps/search/?api=1&query=${encodeURIComponent(data.region + ', ' + data.country)}`;
  const score = parseInt(data.criticScores?.[0]?.score || '0');
  const rating5Scale = score > 0 ? (score / 20).toFixed(1) : 'N/A';

  const handleAddToCellarSubmit = () => { 
    onAddToCellar(data, cellarQty, cellarPrice ? parseFloat(cellarPrice) : undefined); 
    setShowCellarModal(false); 
  };

  return (
    <div className="pb-32 space-y-8 px-4 animate-fade-in">

      {/* 1. HERO SNAPSHOT */}
      <div className="glass-card rounded-[3rem] p-6 editorial-shadow border-white/80 overflow-hidden relative">
        <div className="absolute top-0 left-0 w-full h-1.5 bg-gradient-to-r from-dustyGold-400 via-velvet-800 to-dustyGold-400 opacity-80"></div>

        <div className="flex gap-6 mb-8">
          <div className="w-32 shrink-0">
             <div className="aspect-[3/4.5] rounded-2xl overflow-hidden bg-stone-100 shadow-2xl relative ring-4 ring-white">
                <img 
                  src={displayImage} 
                  onError={handleImageError}
                  className="w-full h-full object-cover" 
                  alt={data.name} 
                />
                <div className="absolute top-3 left-3 bg-white/95 px-2 py-0.5 rounded-full text-[9px] font-black uppercase tracking-widest text-velvet-950 shadow-sm border border-stone-100">
                  {data.vintage || 'NV'}
                </div>
             </div>
          </div>

          <div className="flex-1 flex flex-col justify-center min-w-0">
              <a href={mapUrl} target="_blank" rel="noopener noreferrer" className="flex items-center gap-1.5 text-stone-400 text-[9px] font-black uppercase tracking-widest mb-2 hover:text-velvet-600 transition-colors">
                  <MapPin className="w-3 h-3 text-dustyGold-500" />
                  <span className="truncate">{data.region}, {data.country}</span>
              </a>
              <h2 className="text-2xl sm:text-3xl font-serif font-black text-velvet-950 leading-[1.1] tracking-tighter mb-3 line-clamp-3 italic">
                  {data.name}
              </h2>
              <div className="flex flex-wrap gap-2">
                 {data.varietals.slice(0, 2).map(v => (
                   <span key={v} className="text-[10px] font-bold text-stone-500 uppercase tracking-wide px-2 py-0.5 bg-champagne-200/50 rounded-md border border-stone-200/30">{v}</span>
                 ))}
              </div>
          </div>
        </div>

        {/* PRICE & SCORE GALLERY PANEL */}
