            <div className="bg-white/80 p-5 flex flex-col items-center text-center">
                <span className="text-[9px] font-black uppercase tracking-widest text-stone-400 mb-2">Market Estimate</span>
                <span className="text-xl font-bold text-velvet-950 tracking-tight">{data.marketPrice}</span>
