import React, { useRef } from 'react';
import { Camera } from 'lucide-react';

interface ScanButtonProps {
  onImageSelect: (file: File) => void;
  disabled: boolean;
}

export const ScanButton: React.FC<ScanButtonProps> = ({ onImageSelect, disabled }) => {
  const fileInputRef = useRef<HTMLInputElement>(null);

  const handleFileChange = (event: React.ChangeEvent<HTMLInputElement>) => {
    if (event.target.files && event.target.files[0]) {
      onImageSelect(event.target.files[0]);
    }
  };

  return (
    <div className="fixed bottom-8 left-0 right-0 flex justify-center z-50">
      <input
        type="file"
        accept="image/*"
        className="hidden"
        ref={fileInputRef}
        onChange={handleFileChange}
      />
      <button
        onClick={() => fileInputRef.current?.click()}
        disabled={disabled}
        className="bg-velvet-950 text-white w-20 h-20 rounded-full shadow-2xl flex items-center justify-center hover:bg-velvet-900 transition-all active:scale-90 disabled:opacity-50 editorial-shadow group relative"
      >
        <div className="absolute inset-0 bg-white/10 rounded-full scale-0 group-hover:scale-100 transition-transform duration-300"></div>
        <Camera className="w-8 h-8 relative z-10" strokeWidth={1.5} />
      </button>
    </div>
  );
};

import React, { useState, useEffect } from 'react';
import { Header } from './components/Header';
import { ScanButton } from './components/ScanButton';
import { WineDisplay } from './components/WineDisplay';
import { CellarDashboard } from './components/CellarDashboard';
import { analyzeWineLabel, searchWineByName } from './services/geminiService';
import { AnalysisState, WineData, CellarItem } from './types';
import { Loader2, AlertCircle, ArrowRight, Sparkles } from 'lucide-react';

const WineListItemThumbnail = ({ src }: { src?: string }) => {
  const [error, setError] = useState(false);
  if (!src || error) {
    return <div className="w-full h-full flex items-center justify-center bg-stone-100 text-stone-300"><span className="text-[10px] font-black">AI</span></div>;
  }
  return <img src={src} alt="" className="w-full h-full object-cover" onError={() => setError(true)} />;
};

const App: React.FC = () => {
  const [imagePreview, setImagePreview] = useState<string | null>(null);
  const [analysis, setAnalysis] = useState<AnalysisState>({ status: 'idle' });
  const [searchQuery, setSearchQuery] = useState('');
  const [history, setHistory] = useState<WineData[]>([]);
  const [cellar, setCellar] = useState<CellarItem[]>([]);
  const [activeTab, setActiveTab] = useState<'recent' | 'cellar'>('recent');

  useEffect(() => {
    try {
      const savedHistory = localStorage.getItem('wineHistory');
      if (savedHistory) setHistory(JSON.parse(savedHistory));
      const savedCellar = localStorage.getItem('wineCellar');
      if (savedCellar) setCellar(JSON.parse(savedCellar));
    } catch (e) { console.error(e); }
  }, []);

  const saveToHistory = (data: WineData) => {
    setHistory(prev => {
      const filtered = prev.filter(item => !(item.name === data.name && item.vintage === data.vintage));
      const newHistory = [data, ...filtered].slice(0, 10);
      localStorage.setItem('wineHistory', JSON.stringify(newHistory));
      return newHistory;
    });
  };

  const handleWineUpdate = (updatedData: WineData) => {
    if (analysis.status === 'success' && analysis.data?.id === updatedData.id) {
        setAnalysis(prev => ({ ...prev, data: updatedData }));
    }
    setHistory(prev => {
        const newHist = prev.map(item => (item.id === updatedData.id ? updatedData : item));
        localStorage.setItem('wineHistory', JSON.stringify(newHist));
        return newHist;
    });
    setCellar(prev => {
        const newCellar = prev.map(item => item.wine.id === updatedData.id ? { ...item, wine: updatedData } : item);
        localStorage.setItem('wineCellar', JSON.stringify(newCellar));
        return newCellar;
    });
  };

  const handleAddToCellar = (wine: WineData, quantity: number, price?: number) => {
      setCellar(prev => {
          const existingIndex = prev.findIndex(i => i.wine.name === wine.name && i.wine.vintage === wine.vintage);
          let newCellar;
          if (existingIndex >= 0) {
              newCellar = [...prev];
              newCellar[existingIndex].quantity += quantity;
              if (price) newCellar[existingIndex].purchasePrice = price;
          } else {
              const newItem: CellarItem = {
                  id: `${Date.now()}-${Math.random()}`,
                  wine, quantity, purchasePrice: price, addedAt: Date.now()
              };
              newCellar = [newItem, ...prev];
          }
          localStorage.setItem('wineCellar', JSON.stringify(newCellar));
          return newCellar;
      });
  };

  const updateCellarQuantity = (id: string, delta: number) => {
      setCellar(prev => {
          const newCellar = prev.map(item => item.id === id ? { ...item, quantity: Math.max(0, item.quantity + delta) } : item).filter(item => item.quantity > 0);
          localStorage.setItem('wineCellar', JSON.stringify(newCellar));
          return newCellar;
      });
  };

  const removeCellarItem = (id: string) => {
      setCellar(prev => {
          const newCellar = prev.filter(item => item.id !== id);
          localStorage.setItem('wineCellar', JSON.stringify(newCellar));
          return newCellar;
      });
  };

  const handleImageSelect = async (file: File) => {
    const reader = new FileReader();
    reader.onloadend = () => setImagePreview(reader.result as string);
    reader.readAsDataURL(file);
    setAnalysis({ status: 'analyzing' });
    try {
      const base64Data = await new Promise<string>((resolve, reject) => {
        const r = new FileReader();
        r.readAsDataURL(file);
        r.onload = () => resolve((r.result as string).split(',')[1]);
        r.onerror = e => reject(e);
      });
      const data = await analyzeWineLabel(base64Data, file.type);
      setAnalysis({ status: 'success', data });
      saveToHistory(data);
    } catch (e) { setAnalysis({ status: 'error', error: "Could not identify label" }); }
  };

  const handleTextSearch = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!searchQuery.trim()) return;
    setImagePreview(null);
    setAnalysis({ status: 'analyzing' });
    try {
      const data = await searchWineByName(searchQuery);
      setAnalysis({ status: 'success', data });
      saveToHistory(data);
    } catch (e) { setAnalysis({ status: 'error', error: "Wine not found" }); }
  };

  return (
    <div className="min-h-screen bg-champagne-100 flex flex-col">
      <Header />

      <main className="max-w-md mx-auto w-full flex-grow px-4 pb-40">

        {analysis.status === 'idle' && (
          <div className="flex justify-center gap-8 mb-12">
              <button 
                onClick={() => setActiveTab('recent')} 
                className={`text-[10px] font-black uppercase tracking-[0.3em] transition-all pb-1 border-b-2 ${activeTab === 'recent' ? 'border-velvet-800 text-velvet-950' : 'border-transparent text-stone-300'}`}
              >
                Search
              </button>
              <button 
                onClick={() => setActiveTab('cellar')} 
                className={`text-[10px] font-black uppercase tracking-[0.3em] transition-all pb-1 border-b-2 ${activeTab === 'cellar' ? 'border-velvet-800 text-velvet-950' : 'border-transparent text-stone-300'}`}
              >
                Cellar
              </button>
          </div>
        )}

        {analysis.status === 'idle' && activeTab === 'cellar' && (
           <CellarDashboard items={cellar} onUpdateQuantity={updateCellarQuantity} onRemoveItem={removeCellarItem} onViewWine={(w) => { setAnalysis({ status: 'success', data: w }); setActiveTab('recent'); }} />
        )}

        {analysis.status === 'idle' && activeTab === 'recent' && (
          <div className="space-y-12 animate-fade-in">
            <div className="glass-card rounded-[3rem] p-8 editorial-shadow border-white/80">
              <h2 className="text-3xl font-serif font-black text-velvet-950 mb-6 italic tracking-tighter">Manual Query</h2>
              <form onSubmit={handleTextSearch} className="relative mb-6">
                <input 
                  type="text"
                  placeholder="Vintage, Estate, Varietal..."
                  value={searchQuery}
                  onChange={(e) => setSearchQuery(e.target.value)}
                  className="w-full bg-champagne-100/50 border-b-2 border-stone-200 py-4 pr-12 text-xl font-serif italic text-velvet-950 placeholder:text-stone-300 focus:outline-none focus:border-dustyGold-500 transition-colors"
                />
                <button type="submit" disabled={!searchQuery.trim()} className="absolute right-0 top-1/2 -translate-y-1/2 text-stone-400 hover:text-velvet-900 transition-colors">
                  <ArrowRight className="w-6 h-6" />
                </button>
              </form>
              <div className="flex items-start gap-4 p-5 bg-stone-100/50 rounded-2xl">
                <Sparkles className="w-4 h-4 text-dustyGold-500 mt-1" />
                <p className="text-xs font-medium text-stone-500 leading-relaxed italic">Include the vintage year for precise historical data and current market valuation.</p>
              </div>
            </div>

            <div className="space-y-6">
                <h3 className="text-[10px] font-black text-stone-400 uppercase tracking-widest ml-4">Recently Curated</h3>
                <div className="space-y-4">
                    {history.length > 0 ? history.map((item, idx) => (
                        <div key={idx} onClick={() => { setAnalysis({ status: 'success', data: item }); setImagePreview(item.onlineImage || null); }} className="glass-card rounded-2xl p-4 flex items-center gap-4 hover:bg-white/80 cursor-pointer transition-all editorial-shadow active:scale-98">
                            <div className="w-14 h-14 bg-white rounded-xl overflow-hidden border border-stone-100">
                                <WineListItemThumbnail src={item.onlineImage} />
                            </div>
                            <div className="flex-1 min-w-0">
                                <p className="font-serif font-black italic text-velvet-950 text-lg leading-tight truncate">{item.name}</p>
                                <p className="text-[9px] font-black text-stone-400 uppercase tracking-widest mt-1">{item.vintage} • {item.region}</p>
                            </div>
                            <span className="text-lg font-serif font-black italic text-dustyGold-600 pr-2">{item.criticScores?.[0]?.score || '-'}</span>
                        </div>
                    )) : <p className="text-center text-stone-300 text-xs italic py-8">Your curated history will appear here.</p>}
                </div>
            </div>
          </div>
        )}

        {analysis.status === 'analyzing' && (
          <div className="flex flex-col items-center justify-center py-20 px-6 text-center">
            <div className="relative mb-12">
              <div className="absolute inset-0 bg-dustyGold-100 rounded-full animate-ping opacity-25"></div>
              <div className="relative bg-white p-6 rounded-full shadow-2xl border border-stone-100">
                <Loader2 className="w-10 h-10 text-velvet-800 animate-spin" strokeWidth={1.5} />
              </div>
            </div>
            <h3 className="text-3xl font-serif font-black italic text-velvet-950 tracking-tighter">Consulting Archive</h3>
            <p className="text-stone-400 mt-4 text-xs font-bold uppercase tracking-widest">Cross-referencing global databases...</p>
          </div>
        )}

        {analysis.status === 'success' && analysis.data && (
          <div className="animate-slide-up">
            <button onClick={() => { setAnalysis({ status: 'idle' }); setSearchQuery(''); setImagePreview(null); }} className="mb-6 ml-6 text-[9px] font-black text-stone-300 uppercase tracking-widest hover:text-velvet-800 transition-colors flex items-center gap-2">
              <ArrowRight className="w-3 h-3 rotate-180" /> Back to Dashboard
            </button>
            <WineDisplay data={analysis.data} imagePreview={imagePreview} isFavorite={false} onToggleFavorite={() => {}} onUpdateWine={handleWineUpdate} onAddToCellar={handleAddToCellar} />
          </div>
        )}

        {analysis.status === 'error' && (
          <div className="text-center py-20 px-10">
            <AlertCircle className="w-12 h-12 text-velvet-600 mx-auto mb-6 opacity-30" />
            <h3 className="text-2xl font-serif font-black text-velvet-950 italic mb-2">Identification Failed</h3>
            <p className="text-stone-500 text-sm mb-10 leading-relaxed">The archives were unable to match this label. Please check lighting or try manual entry.</p>
