}
`;

const parseResponse = (text: string, groundingMetadata: any): WineData => {
  if (!text) throw new Error("Empty response from AI");

  // Clean potential markdown leftovers if the model hallucinates them despite system instructions
  const cleanJson = text.trim().replace(/^```json/, '').replace(/```$/, '').trim();

  try {
    const data: WineData = JSON.parse(cleanJson);
    data.timestamp = Date.now();
    data.id = `${data.name}-${data.vintage}-${Date.now()}`;

    if (!data.onlineImage && data.imageCandidates?.length) {
      data.onlineImage = data.imageCandidates[0];
    }

    const sources: string[] = [];
    groundingMetadata?.groundingChunks?.forEach((chunk: any) => {
      if (chunk.web?.uri) {
        sources.push(chunk.web.title || chunk.web.uri);
      }
    });

    return { ...data, sources: [...new Set(sources)] };
  } catch (error) {
    console.error("Failed to parse WineData JSON:", cleanJson);
    throw new Error("The AI returned malformed data. Please try again.");
  }
};

export const analyzeWineLabel = async (base64: string, mimeType: string): Promise<WineData> => {
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
  const response = await ai.models.generateContent({
    model: 'gemini-3-flash-preview',
    contents: {
      parts: [
        { inlineData: { data: base64, mimeType } },
        { text: "Examine this label. Research the specific estate and vintage. Return a complete dossier in JSON." }
      ]
    },
    config: {
      systemInstruction: SYSTEM_INSTRUCTION,
      responseMimeType: "application/json",
      tools: [{ googleSearch: {} }]
    }
  });

  return parseResponse(response.text, response.candidates?.[0]?.groundingMetadata);
};

export const searchWineByName = async (query: string): Promise<WineData> => {
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
  const response = await ai.models.generateContent({
    model: 'gemini-3-flash-preview',
    contents: `Retrieve a sommelier report for: "${query}".`,
    config: {
      systemInstruction: SYSTEM_INSTRUCTION,
      responseMimeType: "application/json",
      tools: [{ googleSearch: {} }]
    }
  });

  return parseResponse(response.text, response.candidates?.[0]?.groundingMetadata);
};

export const searchWineMatches = async (query: string): Promise<WineMatch[]> => {
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
  const response = await ai.models.generateContent({
    model: 'gemini-3-flash-preview',
    contents: `User is searching for: "${query}". List 3-5 specific matching wine estate and vintage combinations.`,
    config: {
      responseMimeType: "application/json",
      responseSchema: {
        type: Type.ARRAY,
        items: {
          type: Type.OBJECT,
          properties: {
            name: { type: Type.STRING },
            vintage: { type: Type.STRING },
            region: { type: Type.STRING },
          },
          required: ['name', 'vintage', 'region']
        }
      }
    }
  });

  return JSON.parse(response.text || "[]");
};

