      const data = await searchWineByName(`${choice.name} ${choice.vintage}`);
      setAnalysis({ status: 'success', data });
      saveToHistory(data);
    } catch (e) {
      setAnalysis({ status: 'error', error: "Failed to retrieve full report." });
    }
  };

  return (
