};

import React, { useState, useEffect } from 'react';
import { WineData } from '../types';
import { MapPin, Droplet, TrendingUp, Utensils, Thermometer, Wine as WineIcon, Mountain, ExternalLink, Lightbulb, Clock, BookOpen, ChevronDown, ChevronUp, Activity, FileDown, Award, Star, PenLine, Sparkles, GraduationCap, Sun, Plus, Package, Share2 } from 'lucide-react';
import { VintageChart } from './VintageChart';
import { CompositionChart } from './CompositionChart';
import { TastingCard } from './TastingCard';

interface WineDisplayProps {
  data: WineData;
  imagePreview: string | null;
  onUpdateWine: (updatedData: WineData) => void;
  onAddToCellar: (wine: WineData, quantity: number, price?: number) => void;
  onToast: (text: string, type?: 'success' | 'info') => void;
}

const countryCodeMap: Record<string, string> = {
  'italy': 'it', 'france': 'fr', 'spain': 'es', 'united states': 'us', 'usa': 'us',
  'argentina': 'ar', 'chile': 'cl', 'australia': 'au', 'germany': 'de', 'portugal': 'pt',
  'south africa': 'za', 'new zealand': 'nz', 'austria': 'at', 'hungary': 'hu', 'greece': 'gr',
  'china': 'cn', 'japan': 'jp', 'uruguay': 'uy', 'brazil': 'br', 'canada': 'ca', 'switzerland': 'ch',
  'united kingdom': 'gb', 'england': 'gb'
};

const StyleMeter = ({ label, value }: { label: string; value: string }) => {
  const getPercentage = (val: string) => {
    const v = val.toLowerCase();
    if (v.includes('high') || v.includes('full') || v.includes('intense')) return 95;
    if (v.includes('medium-plus') || v.includes('med+')) return 75;
    if (v.includes('medium') || v.includes('moderate')) return 50;
    if (v.includes('low') || v.includes('light')) return 25;
    if (v.includes('silky') || v.includes('smooth')) return 60;
    return 50;
  };
  const pct = getPercentage(value);
  return (
    <div className="mb-4">
      <div className="flex justify-between items-end mb-1.5">
        <span className="text-[10px] uppercase tracking-widest font-bold text-stone-400">{label}</span>
        <span className="text-xs font-bold text-wine-900">{value}</span>
      </div>
      <div className="h-1.5 w-full bg-stone-100 rounded-full overflow-hidden">
        <div className="h-full bg-gradient-to-r from-wine-400 to-wine-600 rounded-full transition-all duration-1000" style={{ width: `${pct}%` }}></div>
      </div>
    </div>
  );
};

const CollapsibleSection = ({ title, icon: Icon, children, defaultOpen = false }: { title: string; icon: React.ElementType; children?: React.ReactNode; defaultOpen?: boolean; }) => {
  const [isOpen, setIsOpen] = useState(defaultOpen);
  return (
    <div className="bg-white border border-stone-100 rounded-2xl overflow-hidden shadow-sm transition-all duration-300">
      <button onClick={() => setIsOpen(!isOpen)} className="w-full flex items-center justify-between p-5 bg-white hover:bg-stone-50 transition-colors group">
        <div className="flex items-center gap-3">
          <div className="p-2 bg-wine-50 rounded-lg text-wine-600 group-hover:bg-wine-100 transition-colors">
            <Icon className="w-4 h-4" />
          </div>
          <span className="font-serif font-bold text-wine-900 tracking-tight text-lg">{title}</span>
        </div>
        {isOpen ? <ChevronUp className="w-4 h-4 text-stone-400" /> : <ChevronDown className="w-4 h-4 text-stone-400" />}
      </button>
      <div className={`grid transition-[grid-template-rows,opacity] duration-500 ease-in-out ${isOpen ? 'grid-rows-[1fr] opacity-100' : 'grid-rows-[0fr] opacity-0'}`}>
        <div className="overflow-hidden"><div className="p-5 pt-0 border-t border-dashed border-stone-100"><div className="pt-4">{children}</div></div></div>
      </div>
    </div>
  );
};

export const WineDisplay: React.FC<WineDisplayProps> = ({ data, imagePreview, onUpdateWine, onAddToCellar, onToast }) => {
  const [currentImageIndex, setCurrentImageIndex] = useState(0);
  const [usingFallback, setUsingFallback] = useState(false);
  const [showCellarModal, setShowCellarModal] = useState(false);
  const [showTastingCard, setShowTastingCard] = useState(false);
  const [cellarQty, setCellarQty] = useState(1);
  const [cellarPrice, setCellarPrice] = useState('');
  const [noteText, setNoteText] = useState(data.userNotes || '');

  useEffect(() => {
    setCurrentImageIndex(0);
    setUsingFallback(false);
    setNoteText(data.userNotes || '');
    setCellarQty(1);
    setCellarPrice('');
  }, [data]);

  const fallbackImage = 'https://images.unsplash.com/photo-1559563362-c667ba5f5480?auto=format&fit=crop&q=80&w=600';
  const getFlagUrl = () => {
      if (!data.country) return null;
      const key = data.country.toLowerCase().trim();
      if (countryCodeMap[key]) return `https://flagcdn.com/w640/${countryCodeMap[key]}.png`;
      return null;
  };
  const getDisplayImage = () => {
    if (imagePreview) return imagePreview;
    if (usingFallback) return getFlagUrl() || fallbackImage;
    const candidates = data.imageCandidates || (data.onlineImage ? [data.onlineImage] : []);
    if (candidates.length > 0 && currentImageIndex < candidates.length) return candidates[currentImageIndex];
    return getFlagUrl() || fallbackImage;
  };
  const handleImageError = () => {
    const candidates = data.imageCandidates || (data.onlineImage ? [data.onlineImage] : []);
    if (currentImageIndex < candidates.length - 1) setCurrentImageIndex(prev => prev + 1);
    else setUsingFallback(true);
  };
  const displayImage = getDisplayImage();
  const mapUrl = `https://www.google.com/maps/search/?api=1&query=${encodeURIComponent(`${data.region}, ${data.country}`)}`;
  const score = parseInt(data.criticScores?.[0]?.score || '0');
  const rating5Scale = score > 0 ? (score / 20).toFixed(1) : 'N/A';
  const valueBadge = score >= 95 ? { label: "Iconic", color: "bg-purple-100 text-purple-700 border-purple-200" } : score >= 90 ? { label: "Excellent Value", color: "bg-emerald-100 text-emerald-700 border-emerald-200" } : score >= 85 ? { label: "Good Value", color: "bg-amber-100 text-amber-700 border-amber-200" } : null;

  const handleRating = (rating: number) => onUpdateWine({ ...data, userRating: rating });
  const handleNoteBlur = () => { if (noteText !== data.userNotes) onUpdateWine({ ...data, userNotes: noteText }); };
  const handleAddToCellarSubmit = () => { onAddToCellar(data, cellarQty, cellarPrice ? parseFloat(cellarPrice) : undefined); setShowCellarModal(false); };
  const ensureAbsoluteUrl = (url: string) => (!url || url.startsWith('http')) ? url : `https://${url}`;

  const exportReport = () => {
      const htmlContent = `<html><head><title>${data.name}</title><style>body { font-family: sans-serif; padding: 20px; line-height: 1.6; color: #333; } h1 { color: #882333; border-bottom: 2px solid #eee; padding-bottom: 10px; } .notes { background: #f9f9f9; padding: 15px; border-left: 4px solid #882333; font-style: italic; }</style></head><body><h1>${data.name}</h1><p><strong>Vintage:</strong> ${data.vintage} | <strong>Region:</strong> ${data.region}, ${data.country}</p><p><strong>Market Price:</strong> ${data.marketPrice} | <strong>Score:</strong> ${data.criticScores?.[0]?.score || 'N/A'}</p><h2>Sensory Profile</h2><div class="notes">"${data.nose}. ${data.taste}"</div><h2>Winery Info</h2><p>${data.wineryInfo}</p></body></html>`;
      const blob = new Blob([htmlContent], { type: 'text/html' });
      const item = new ClipboardItem({ "text/html": blob });
      navigator.clipboard.write([item]).then(() => onToast("Report copied to clipboard!", "success")).catch(() => onToast("Export failed", "info"));
  };

  return (
    <div className="pb-24 space-y-6 relative">
      {showCellarModal && (
        <div className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-black/40 backdrop-blur-sm animate-fade-in">
           <div className="bg-white rounded-3xl p-6 w-full max-w-sm shadow-2xl animate-scale-up">
              <h3 className="text-xl font-serif font-bold text-wine-900 mb-4">Add to Cellar</h3>
              <div className="space-y-4">
                 <div>
                    <label className="text-[10px] font-bold text-stone-400 uppercase tracking-widest block mb-1">Quantity</label>
