const CollapsibleSection = ({ title, icon: Icon, children, defaultOpen = false }: { title: string; icon: React.ElementType; children?: React.ReactNode; defaultOpen?: boolean; }) => {
  const [isOpen, setIsOpen] = useState(defaultOpen);
  return (
    <div className="bg-white border border-stone-100 rounded-2xl overflow-hidden shadow-sm transition-all duration-300">
      <button onClick={() => setIsOpen(!isOpen)} className="w-full flex items-center justify-between p-5 bg-white hover:bg-stone-50 transition-colors group">
        <div className="flex items-center gap-3">
          <div className="p-2 bg-wine-50 rounded-lg text-wine-600 group-hover:bg-wine-100 transition-colors">
            <Icon className="w-4 h-4" />
          </div>
          <span className="font-serif font-bold text-wine-900 tracking-tight text-lg">{title}</span>
        </div>
        {isOpen ? <ChevronUp className="w-4 h-4 text-stone-400" /> : <ChevronDown className="w-4 h-4 text-stone-400" />}
      </button>
      <div className={`grid transition-[grid-template-rows,opacity] duration-500 ease-in-out ${isOpen ? 'grid-rows-[1fr] opacity-100' : 'grid-rows-[0fr] opacity-0'}`}>
        <div className="overflow-hidden"><div className="p-5 pt-0 border-t border-dashed border-stone-100"><div className="pt-4">{children}</div></div></div>
      </div>
    </div>
  );
};

export const WineDisplay: React.FC<WineDisplayProps> = ({ data, imagePreview, onUpdateWine, onAddToCellar, onToast }) => {
  const [currentImageIndex, setCurrentImageIndex] = useState(0);
  const [usingPlaceholder, setUsingPlaceholder] = useState(false);
  const [showCellarModal, setShowCellarModal] = useState(false);
  const [showTastingCard, setShowTastingCard] = useState(false);
  const [cellarQty, setCellarQty] = useState(1);
  const [cellarPrice, setCellarPrice] = useState('');
  const [noteText, setNoteText] = useState(data.userNotes || '');

  useEffect(() => {
    setCurrentImageIndex(0);
    setUsingPlaceholder(false);
    setNoteText(data.userNotes || '');
    setCellarQty(1);
    setCellarPrice('');
  }, [data]);

  const getDisplayImage = () => {
    if (imagePreview) return imagePreview;
    if (data.localImage) return data.localImage;

    const candidates = data.imageCandidates || (data.onlineImage ? [data.onlineImage] : []);
    if (candidates.length > 0 && currentImageIndex < candidates.length) return candidates[currentImageIndex];

    return null;
  };

  const handleImageError = () => {
    const candidates = data.imageCandidates || (data.onlineImage ? [data.onlineImage] : []);
    if (currentImageIndex < candidates.length - 1) setCurrentImageIndex(prev => prev + 1);
    else setUsingPlaceholder(true);
  };

  const displayImage = getDisplayImage();
  const mapUrl = `https://www.google.com/maps/search/?api=1&query=${encodeURIComponent(`${data.region}, ${data.country}`)}`;
  const score = parseInt(data.criticScores?.[0]?.score || '0');
  const rating5Scale = score > 0 ? (score / 20).toFixed(1) : 'N/A';
  const valueBadge = score >= 95 ? { label: "Iconic", color: "bg-purple-100 text-purple-700 border-purple-200" } : score >= 90 ? { label: "Excellent Value", color: "bg-emerald-100 text-emerald-700 border-emerald-200" } : score >= 85 ? { label: "Good Value", color: "bg-amber-100 text-amber-700 border-amber-200" } : null;

  const handleRating = (rating: number) => onUpdateWine({ ...data, userRating: rating });
  const handleNoteBlur = () => { if (noteText !== data.userNotes) onUpdateWine({ ...data, userNotes: noteText }); };
  const handleAddToCellarSubmit = () => { onAddToCellar(data, cellarQty, cellarPrice ? parseFloat(cellarPrice) : undefined); setShowCellarModal(false); };
  const ensureAbsoluteUrl = (url: string) => (!url || url.startsWith('http')) ? url : `https://${url}`;

  const exportReport = () => {
      const htmlContent = `<html><head><title>${data.name}</title><style>body { font-family: sans-serif; padding: 20px; line-height: 1.6; color: #333; } h1 { color: #882333; border-bottom: 2px solid #eee; padding-bottom: 10px; } .notes { background: #f9f9f9; padding: 15px; border-left: 4px solid #882333; font-style: italic; }</style></head><body><h1>${data.name}</h1><p><strong>Vintage:</strong> ${data.vintage} | <strong>Region:</strong> ${data.region}, ${data.country}</p><p><strong>Market Price:</strong> ${data.marketPrice} | <strong>Score:</strong> ${data.criticScores?.[0]?.score || 'N/A'}</p><h2>Sensory Profile</h2><div class="notes">"${data.nose}. ${data.taste}"</div><h2>Winery Info</h2><p>${data.wineryInfo}</p></body></html>`;
      const blob = new Blob([htmlContent], { type: 'text/html' });
      const item = new ClipboardItem({ "text/html": blob });
      navigator.clipboard.write([item]).then(() => onToast("Report copied to clipboard!", "success")).catch(() => onToast("Export failed", "info"));
  };

  return (
    <div className="pb-24 space-y-6 relative">
      {showCellarModal && (
        <div className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-black/40 backdrop-blur-sm animate-fade-in">
           <div className="bg-white rounded-3xl p-6 w-full max-w-sm shadow-2xl animate-scale-up">
              <h3 className="text-xl font-serif font-bold text-wine-900 mb-4">Add to Cellar</h3>
              <div className="space-y-4">
                 <div>
                    <label className="text-[10px] font-bold text-stone-400 uppercase tracking-widest block mb-1">Quantity</label>
                    <div className="flex items-center gap-4">
                       <button onClick={() => setCellarQty(Math.max(1, cellarQty - 1))} className="w-10 h-10 rounded-full border border-stone-200 flex items-center justify-center hover:bg-stone-50"><span className="text-lg font-bold">-</span></button>
                       <span className="text-2xl font-bold text-wine-900 w-8 text-center">{cellarQty}</span>
                       <button onClick={() => setCellarQty(cellarQty + 1)} className="w-10 h-10 rounded-full bg-wine-50 border border-wine-100 flex items-center justify-center hover:bg-wine-100"><Plus className="w-5 h-5 text-wine-800" /></button>
                    </div>
                 </div>
                 <div>
                    <label className="text-[10px] font-bold text-stone-400 uppercase tracking-widest block mb-1">Purchase Price (Per Bottle)</label>
                    <div className="relative">
                       <span className="absolute left-3 top-1/2 -translate-y-1/2 text-stone-400 font-bold">$</span>
                       <input type="number" value={cellarPrice} onChange={e => setCellarPrice(e.target.value)} placeholder="Optional" className="w-full pl-7 pr-4 py-3 bg-stone-50 border border-stone-200 rounded-xl font-bold text-wine-900 focus:outline-none focus:ring-2 focus:ring-wine-200" />
                    </div>
                 </div>
              </div>
              <div className="grid grid-cols-2 gap-3 mt-6">
                 <button onClick={() => setShowCellarModal(false)} className="py-3 rounded-xl font-bold text-stone-500 hover:bg-stone-50">Cancel</button>
                 <button onClick={handleAddToCellarSubmit} className="py-3 rounded-xl bg-wine-900 text-white font-bold shadow-lg shadow-wine-900/20 hover:bg-wine-800">Save to Cellar</button>
              </div>
           </div>
        </div>
      )}

      {showTastingCard && <TastingCard wine={data} onClose={() => setShowTastingCard(false)} />}

      {/* ZONE 1: SNAPSHOT */}
      <div className="bg-white rounded-[2.5rem] p-4 shadow-xl border border-wine-100/50 relative overflow-hidden mx-4">
        <div className="absolute -top-10 -right-10 w-40 h-40 bg-wine-50 rounded-full blur-3xl"></div>
        <div className="relative z-10">
            <div className="flex gap-4 mb-4">
                <div className="w-28 sm:w-1/3 shrink-0">
                   <div className="aspect-[3/4] rounded-2xl overflow-hidden bg-stone-100 border border-stone-100 shadow-md relative flex items-center justify-center group">
                     {displayImage && !usingPlaceholder ? (
                        <img src={displayImage} onError={handleImageError} className={`w-full h-full object-cover transition-transform duration-500 group-hover:scale-105`} alt={data.name} />
                     ) : (
                        <WineBottlePlaceholder />
                     )}
                     {data.vintage && <div className="absolute top-2 left-2 bg-white/90 text-wine-900 text-[10px] font-bold px-2 py-0.5 rounded-full shadow-sm backdrop-blur-md z-20">{data.vintage}</div>}
                   </div>
                </div>
                <div className="flex-1 flex flex-col min-w-0">
                    <a href={mapUrl} target="_blank" rel="noopener noreferrer" className="flex items-center gap-1.5 text-wine-600 hover:text-wine-800 text-[10px] font-bold uppercase tracking-widest mb-1 cursor-pointer transition-colors">
                        <MapPin className="w-3 h-3" /><span className="line-clamp-1 underline decoration-dotted underline-offset-2">{data.country}</span>
                    </a>
                    <h2 className="text-xl sm:text-3xl font-sans font-black text-wine-950 leading-[1.1] tracking-tight mb-2 line-clamp-3">
                      {data.name}
                    </h2>
                    <div className="flex flex-wrap gap-1.5 mb-2">
                        <span className="px-2 py-0.5 bg-wine-50 text-wine-900 text-[9px] font-bold rounded-md uppercase tracking-wide border border-wine-100 truncate max-w-full">{data.region}</span>
                        {data.varietals.slice(0, 1).map(v => <span key={v} className="px-2 py-0.5 bg-stone-100 text-stone-600 text-[9px] font-bold rounded-md uppercase tracking-wide border border-stone-200">{v}</span>)}
                    </div>
                    <div className="mb-2.5">
                       <p className="text-[10px] sm:text-xs text-stone-500 font-medium leading-relaxed line-clamp-3">A {data.styleProfile?.body ? data.styleProfile.body.toLowerCase() : 'classic'} {data.type.toLowerCase()} with {data.abv}. Notes of {data.nose.split(',').slice(0, 2).join(', ')}.</p>
                    </div>
                </div>
            </div>
            <div className="bg-stone-50 rounded-xl p-3 border border-stone-100 flex items-center justify-between shadow-sm gap-4 relative overflow-hidden">
                <div className="flex-1 min-w-0 flex flex-col justify-center">
                     <p className="text-[10px] text-stone-500 uppercase tracking-widest font-bold mb-1">Market Price</p>
                     <p className="text-xl sm:text-2xl font-sans font-bold text-wine-950 tabular-nums tracking-tight leading-tight whitespace-normal break-words">{data.marketPrice}</p>
                </div>
                <div className="w-px h-10 bg-stone-200/80"></div>
                {score > 0 ? (
                    <div className="flex flex-col items-end shrink-0 z-10">
                        <div className="flex items-center gap-2">
                            <span className="text-2xl sm:text-3xl font-bold text-wine-900 leading-none tracking-tighter">{rating5Scale}</span>
                            <div className="bg-wine-900 text-white text-[10px] font-bold px-1.5 py-0.5 rounded shadow-sm min-w-[28px] text-center self-start mt-1">{score}</div>
                        </div>
                        <div className="flex items-center gap-2 mt-1">
                            <div className="flex -space-x-0.5">{[1,2,3,4,5].map(i => <Star key={i} className={`w-3 h-3 ${i <= Math.round(Number(rating5Scale)) ? 'fill-gold-500 text-gold-500' : 'text-stone-300'}`} />)}</div>
                            {valueBadge && <span className={`text-[8px] font-bold px-1.5 py-0.5 rounded uppercase tracking-wide border bg-white ${valueBadge.color.replace('bg-', 'text-').replace('text-', 'border-')}`}>{valueBadge.label}</span>}
                        </div>
                    </div>
                ) : <div className="text-right py-1"><span className="text-xs text-stone-400 italic">No rating</span></div>}
            </div>
        </div>
      </div>

      {/* Quick Action Overlay (Phase 3.0 Polish) */}
      <div className="px-6 flex justify-end">
         <button onClick={() => setShowTastingCard(true)} className="flex items-center gap-2 text-[10px] font-black uppercase tracking-[0.2em] text-wine-900 bg-white border border-wine-100 px-4 py-2 rounded-full shadow-lg hover:bg-wine-50 transition-all active:scale-95">
           <Share2 className="w-3 h-3" /> Share Tasting Card
