      const htmlContent = `<html><head><title>${data.name}</title><style>body { font-family: sans-serif; padding: 20px; line-height: 1.6; color: #333; } h1 { color: #882333; border-bottom: 2px solid #eee; padding-bottom: 10px; } .notes { background: #f9f9f9; padding: 15px; border-left: 4px solid #882333; font-style: italic; }</style></head><body><h1>${data.name}</h1><p><strong>Vintage:</strong> ${data.vintage} | <strong>Region:</strong> ${data.region}, ${data.country}</p><p><strong>Market Price:</strong> ${data.marketPrice} | <strong>Score:</strong> ${data.criticScores?.[0]?.score || 'N/A'}</p><h2>Sensory Profile</h2><div class="notes">"${data.nose}. ${data.taste}"</div><h2>Winery Info</h2><p>${data.wineryInfo}</p></body></html>`;
