const estimatePrice = (priceStr: string): number => {
  if (!priceStr) return 0;
  const clean = priceStr.replace(/[^\d.-]/g, '');
  if (clean.includes('-')) {
    const [min, max] = clean.split('-').map(Number);
    return (min + max) / 2;
  }
  return Number(clean) || 0;
};

const WineInventoryThumbnail = ({ wine }: { wine: WineData }) => {
  const [error, setError] = useState(false);
  const src = wine.localImage || wine.onlineImage;

  if (!src || error) {
    return (
      <div className="w-full h-full flex items-center justify-center bg-wine-50/50 p-2">
        <AppIllustration className="w-full h-full drop-shadow-sm" />
      </div>
    );
  }

  return (
    <img 
      src={src} 
      className="w-full h-full object-cover rounded-xl" 
      alt={wine.name} 
      onError={() => setError(true)} 
    />
  );
};

