        </div>

        <div className="mt-5 bg-stone-50 rounded-2xl p-4 border border-stone-100 flex items-center justify-between shadow-sm gap-4 relative overflow-hidden">
            <div className="flex-1 min-w-0">
                 <p className="text-[10px] text-stone-400 uppercase tracking-widest font-bold mb-0.5">Market Price</p>
                 <p className="text-lg sm:text-xl font-sans font-bold text-wine-950 tabular-nums tracking-tight leading-tight">{data.marketPrice}</p>
            </div>
            <div className="w-px h-10 bg-stone-200/80"></div>
            {score > 0 ? (
                <div className="flex flex-col items-end shrink-0">
                    <div className="flex items-center gap-2">
                        <span className="text-2xl sm:text-3xl font-bold text-wine-950 leading-none tracking-tighter">{rating5Scale}</span>
                        <div className="bg-wine-900 text-white text-[10px] font-bold px-1.5 py-0.5 rounded shadow-sm min-w-[28px] text-center">{score}</div>
